test('title-becomes-url-slug: "Hello World" becomes "hello-world"', () => {
  assert.equal(slugify('Hello World'), 'hello-world');
});

test('lower-case: "Hello" becomes "hello"', () => {
  assert.equal(slugify('Hello'), 'hello');
});

test('space-becomes-dash: "big world" becomes "big-world"', () => {
  assert.equal(slugify('big world'), 'big-world');
});

test('space-run-single-dash: "hello   big world" becomes "hello-big-world"', () => {
  assert.equal(slugify('hello   big world'), 'hello-big-world');
});

test('other-characters-dropped: "héllo, wörld 42!" becomes "hllo-wrld-42"', () => {
  assert.equal(slugify('héllo, wörld 42!'), 'hllo-wrld-42');
});

test('digits-kept: "top 42" becomes "top-42"', () => {
  assert.equal(slugify('top 42'), 'top-42');
});

test("title-becomes-url-slug: a title comes back as a URL-safe slug", () => {
  assert.equal(slugify("Hello World"), "hello-world");
});

test("lower-case: upper-case letters come back lower-case", () => {
  assert.equal(slugify("Hello"), "hello");
});

test("spaces-become-single-dash: a run of spaces becomes exactly one dash", () => {
  assert.equal(slugify("hello   big world"), "hello-big-world");
});

test("other-characters-dropped: letters outside a-z and punctuation are removed", () => {
  assert.equal(slugify("héllo, wörld 42!"), "hllo-wrld-42");
});

test('title-becomes-url-slug: "Hello World" becomes "hello-world"', () => {
  assert.equal(slugify('Hello World'), 'hello-world');
});

test('lower-case: "Hello" becomes "hello"', () => {
  assert.equal(slugify('Hello'), 'hello');
});

test('space-becomes-dash: "big world" becomes "big-world"', () => {
  assert.equal(slugify('big world'), 'big-world');
});

test('repeated-spaces-one-dash: "hello   big world" becomes "hello-big-world"', () => {
  assert.equal(slugify('hello   big world'), 'hello-big-world');
});

test('punctuation-dropped: "42!" becomes "42"', () => {
  assert.equal(slugify('42!'), '42');
});

test('accented-letters-dropped: "héllo" becomes "hllo"', () => {
  assert.equal(slugify('héllo'), 'hllo');
});

test('digits-kept: "42" stays "42"', () => {
  assert.equal(slugify('42'), '42');
  // "42" alone passes on code that does nothing, so also check digits survive a real change.
  assert.equal(slugify('R2'), 'r2');
});

test("combined-hours-minutes-to-seconds: 1h30m is 5400 seconds", () => {
  assert.equal(parseDuration("1h30m"), 5400);
});

test("seconds-unit: 45s is 45 seconds", () => {
  assert.equal(parseDuration("45s"), 45);
});

test("minutes-unit: 2m is 120 seconds", () => {
  assert.equal(parseDuration("2m"), 120);
});

test("hours-unit: 1h is 3600 seconds", () => {
  assert.equal(parseDuration("1h"), 3600);
});

test("three-units-summed: 1h30m15s is 5415 seconds", () => {
  assert.equal(parseDuration("1h30m15s"), 5415);
});

test("wrong-unit-order-is-null: 30m1h is rejected", () => {
  assert.equal(parseDuration("30m1h"), null);
  // The stub returns null for everything; the same parts in the right order must parse.
  assert.equal(parseDuration("1h30m"), 5400);
});

test("repeated-unit-is-null: 1h1h is rejected", () => {
  assert.equal(parseDuration("1h1h"), null);
  // The stub returns null for everything; the unit used once must parse.
  assert.equal(parseDuration("1h"), 3600);
});

test("unknown-unit-is-null: 1x is rejected", () => {
  assert.equal(parseDuration("1x"), null);
  // The stub returns null for everything; the same number with a known unit must parse.
  assert.equal(parseDuration("1h"), 3600);
});

test("empty-string-is-null: empty string is rejected", () => {
  assert.equal(parseDuration(""), null);
  // The stub returns null for everything; a non-empty duration must parse.
  assert.equal(parseDuration("45s"), 45);
});

test("text-without-number-is-null: abc is rejected", () => {
  assert.equal(parseDuration("abc"), null);
  // The stub returns null for everything; text with a number must parse.
  assert.equal(parseDuration("45s"), 45);
});

test("bare-number-is-seconds: 90 is 90 seconds", () => {
  assert.equal(parseDuration("90"), 90);
});

test("decimal-part: 1.5h is 5400 seconds", () => {
  assert.equal(parseDuration("1.5h"), 5400);
});

test("space-between-parts: 1h 30m is 5400 seconds", () => {
  assert.equal(parseDuration("1h 30m"), 5400);
});

test("upper-case-units: 1H30M is 5400 seconds", () => {
  assert.equal(parseDuration("1H30M"), 5400);
});

test("combined-units-to-seconds: hours and minutes together give total seconds", () => {
  assert.equal(parseDuration("1h30m"), 5400);
});

test("three-units-summed: hours, minutes and seconds are all added together", () => {
  assert.equal(parseDuration("1h30m15s"), 5415);
});

test("hours-unit: a number followed by h is counted as hours", () => {
  assert.equal(parseDuration("1h"), 3600);
});

test("minutes-unit: a number followed by m is counted as minutes", () => {
  assert.equal(parseDuration("2m"), 120);
});

test("seconds-unit: a number followed by s is counted as seconds", () => {
  assert.equal(parseDuration("45s"), 45);
});

test("bare-number-is-seconds: a bare number with no unit is taken as seconds", () => {
  assert.equal(parseDuration("90"), 90);
});

test("decimal-part: a part can be a decimal number", () => {
  assert.equal(parseDuration("1.5h"), 5400);
});

test("spaces-between-parts: spaces between the parts are allowed", () => {
  assert.equal(parseDuration("1h 30m"), 5400);
});

test("upper-case-units: unit letters can be upper case", () => {
  assert.equal(parseDuration("1H30M"), 5400);
});

test("wrong-order-is-null: units out of largest-to-smallest order return null", () => {
  assert.equal(parseDuration("30m1h"), null);
  // The stub returns null for everything; the same parts in order must parse.
  assert.equal(parseDuration("1h30m"), 5400);
});

test("repeated-unit-is-null: a unit appearing twice returns null", () => {
  assert.equal(parseDuration("1h1h"), null);
  // The stub returns null for everything; the unit appearing once must parse.
  assert.equal(parseDuration("1h"), 3600);
});

test("unknown-unit-is-null: a number with a unit other than h, m or s returns null", () => {
  assert.equal(parseDuration("1x"), null);
  // The stub returns null for everything; the same number with a known unit must parse.
  assert.equal(parseDuration("1h"), 3600);
});

test("non-duration-text-is-null: text with no number in it returns null", () => {
  assert.equal(parseDuration("abc"), null);
  // The stub returns null for everything; a real duration must parse.
  assert.equal(parseDuration("1h"), 3600);
});

test("empty-string-is-null: an empty string returns null", () => {
  assert.equal(parseDuration(""), null);
  // The stub returns null for everything; a non-empty duration must parse.
  assert.equal(parseDuration("1h"), 3600);
});

test("hours-and-minutes-to-seconds: \"1h30m\" is 5400 seconds", () => {
  assert.equal(parseDuration("1h30m"), 5400);
});

test("seconds-unit: \"45s\" is 45 seconds", () => {
  assert.equal(parseDuration("45s"), 45);
});

test("minutes-unit: \"2m\" is 120 seconds", () => {
  assert.equal(parseDuration("2m"), 120);
});

test("hours-unit: \"1h\" is 3600 seconds", () => {
  assert.equal(parseDuration("1h"), 3600);
});

test("three-units-combined: \"1h30m15s\" is 5415 seconds", () => {
  assert.equal(parseDuration("1h30m15s"), 5415);
});

test("bare-number-is-seconds: \"90\" is 90 seconds", () => {
  assert.equal(parseDuration("90"), 90);
});

test("decimal-part: \"1.5h\" is 5400 seconds", () => {
  assert.equal(parseDuration("1.5h"), 5400);
});

test("spaces-between-parts: \"1h 30m\" is 5400 seconds", () => {
  assert.equal(parseDuration("1h 30m"), 5400);
});

test("upper-case-units: \"1H30M\" is 5400 seconds", () => {
  assert.equal(parseDuration("1H30M"), 5400);
});

test("units-out-of-order: \"30m1h\" is null", () => {
  assert.equal(parseDuration("30m1h"), null);
  // the same parts in order are accepted, so null is a real rejection
  assert.equal(parseDuration("1h30m"), 5400);
});

test("repeated-unit: \"1h1h\" is null", () => {
  assert.equal(parseDuration("1h1h"), null);
  // the unit once is accepted, so null is a real rejection
  assert.equal(parseDuration("1h"), 3600);
});

test("unknown-unit: \"1x\" is null", () => {
  assert.equal(parseDuration("1x"), null);
  // the same number with a known unit is accepted, so null is a real rejection
  assert.equal(parseDuration("1h"), 3600);
});

test("text-without-numbers: \"abc\" is null", () => {
  assert.equal(parseDuration("abc"), null);
  // text that is a number is accepted, so null is a real rejection
  assert.equal(parseDuration("90"), 90);
});

test("empty-string: \"\" is null", () => {
  assert.equal(parseDuration(""), null);
  // a non-empty duration is accepted, so null is a real rejection
  assert.equal(parseDuration("90"), 90);
});
